  [inst_4 : Inhabited β] {t : Std.DTreeMap.Internal.Impl α fun x => β},
  t.Ordered → Std.DTreeMap.Internal.Impl.Const.get!ₘ t k = Std.Internal.List.getValue! k t.toListModel

∀ {α : Type u} {cmp : α → α → Ordering} {β : Type v} {m₁ m₂ : Std.DTreeMap.Raw α (fun x => β) cmp}
  [inst : Std.TransCmp cmp] (h₁ : m₁.WF) (h₂ : m₂.WF) {k : α} {h_mem : k ∈ m₁ \ m₂},
  Std.DTreeMap.Raw.Const.get (m₁ \ m₂) k h_mem = Std.DTreeMap.Raw.Const.get m₁ k ⋯

∀ {m : Type u → Type v} {ps : Std.Do.PostShape} {o : Type u → Type u_1} {n : Type u → Type u_2} {α : Type u}
  {Q : Std.Do.PostCond α ps} [inst : Std.Do.WP o ps] [inst_1 : MonadControl n o] [inst_2 : MonadControlT m n]
  (x : stM m o α), ⦃(Std.Do.wp (MonadControl.restoreM (restoreM x))).apply Q⦄ restoreM x ⦃Q⦄

∀ {α : Type} [inst : Hashable α] [inst_1 : DecidableEq α] {aig : Std.Sat.AIG α} (input : aig.BinaryInput)
  (linv rinv : Bool),
  (input.invert linv rinv).rhs = { gate := input.rhs.gate, invert := rinv ^^ input.rhs.invert, hgate := ⋯ }

