∀ {w n m : Nat} {x : BitVec w} (w : Nat) {x : BitVec (w + 1)},
  ¬m < w →
    (x.rotateRight (m % (w + 1))).getMsbD n =
      (decide (n < w + 1) &&
        if n < m % (w + 1) % (w + 1) then x.getMsbD ((w + 1 + n - m % (w + 1) % (w + 1)) % (w + 1))
        else x.getMsbD (n - m % (w + 1) % (w + 1)))

∀ (x : Nat),
  (if 0 = 0 then if (false || true) = true then x else 0
    else
      if x = 0 then if (true || false) = true then 0 else 0
      else
        have n' := 0 / 2;
        have m' := x / 2;
        let b₁ := 0 % 2 = 1;
        let b₂ := x % 2 = 1;
        have r := Nat.bitwise or n' m';
        if (decide b₁ || decide b₂) = true then r + r + 1 else r + r) =
    x

∀ {α : Type u} {x : BEq α} {x_1 : Hashable α} {β : Type v} {m : Std.DHashMap α fun x => β} {l : List (α × β)}
  (m : Std.DHashMap α fun x => β) (x_2 : α × β),
  m.inner.insert x_2.fst x_2.snd = (Std.DHashMap.Internal.Raw₀.insert ⟨m.inner, ⋯⟩ x_2.fst x_2.snd).val

