  [inst_4 : Inhabited β] {t : Std.DTreeMap.Internal.Impl α fun x => β},
  t.Ordered → Std.DTreeMap.Internal.Impl.Const.get!ₘ t k = Std.Internal.List.getValue! k t.toListModel

∀ {α : Type u} {β : Type v} [inst : Ord α] [Std.TransOrd α] [inst_2 : BEq α] [Std.LawfulBEqOrd α] {k : α}
  [inst_4 : Inhabited β] {t : Std.DTreeMap.Internal.Impl α fun x => β},
  t.Ordered → Eq (Std.DTreeMap.Internal.Impl.Const.get!ₘ t k) = Eq (Std.Internal.List.getValue? k t.toListModel).get!

∀ {α : Type u} {β : Type v} [inst : Ord α] [Std.TransOrd α] [inst_2 : BEq α] [Std.LawfulBEqOrd α] {k : α}
  [inst_4 : Inhabited β] {t : Std.DTreeMap.Internal.Impl α fun x => β},
  t.Ordered → (Std.DTreeMap.Internal.Impl.Const.get?ₘ t k).get! = (Std.Internal.List.getValue? k t.toListModel).get!

∀ {α : Type u} {instOrd : Ord α} {β : Type v} {t : Std.DTreeMap.Internal.Impl α fun x => β} [Std.TransOrd α] {k : α}
  {v : β},
  t.WF → (Std.DTreeMap.Internal.Impl.Const.get? t k = some v) = (Std.Internal.List.getValue? k t.toListModel = some v)

∀ {α : Type u} {β : α → Type v} {instOrd : Ord α} {t : Std.DTreeMap.Internal.Impl α β} [Std.TransOrd α] {f : α → Bool}
  {k : α} {fallback : α},
  t.WF → (Option.filter f (t.getKey? k)).getD = (Option.filter f (Std.Internal.List.getKey? k t.toListModel)).getD

∀ {α : Type u} {cmp : α → α → Ordering} {β : Type v} {γ : Type w} {t : Std.DTreeMap.Raw α (fun x => β) cmp}
  [inst : Std.TransCmp cmp] [Std.LawfulEqCmp cmp] [Inhabited γ] {f : α → β → Option γ} {k : α} (h : t.WF) (a : β)
  (h_1 : Std.DTreeMap.Raw.Const.get? t k = some a), f (t.getKey k ⋯) = f k

∀ {α : Type u} {β : Type v} [inst : BEq α] {l : List ((_ : α) × β)} {a : α} {fallback : β}
  (h : Std.Internal.List.containsKey a l = true),
  some (Std.Internal.List.getValue a l h) = some (Std.Internal.List.getValueD a l fallback)

∀ {α : Type u} [inst : LT α] [inst_1 : Std.PRange.UpwardEnumerable α] [inst_2 : Std.Rxi.IsAlwaysFinite α]
  [inst_3 : Std.PRange.LawfulUpwardEnumerable α] [inst_4 : Std.PRange.LawfulUpwardEnumerableLT α] {_a : α}
  {_r : Std.Roi α}, (_a ∈ ForIn.toList _r ↔ _a ∈ _r) = (_a ∈ _r.toList ↔ _a ∈ _r)

∀ {α : Type} [inst : Hashable α] [inst_1 : DecidableEq α] {assign : α → Bool} {aig : Std.Sat.AIG α}
  {input : aig.BinaryInput},
  { aig := aig, ref := (input.invert true true).lhs } =
    { aig := aig, ref := { gate := input.lhs.gate, invert := !input.lhs.invert, hgate := ⋯ } }

∀ {α : Type u} [inst : Std.PRange.UpwardEnumerable α] [Std.PRange.LawfulUpwardEnumerable α] {lo : α}
  (h : (Std.PRange.succ? lo).isSome = true),
  { next := some (Std.PRange.succ? lo).get h...*.lower } = { next := Std.PRange.succ? lo }
